        o: ['(2, 4) [\'sehir\', \'Oca\', \'Şub\', \'Mar\']', '(6, 3) [\'sehir\', \'ay\', \'ciro\']', '(3, 6) [\'sehir\', \'ay\', \'ciro\']', '(6, 2) [\'ay\', \'ciro\']'],
